<?php require 'config/config.php'; $email='admin@odynasties.local'; $password='Admin@12345'; $s=$pdo->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if(!$s->fetch()){$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'admin')")->execute(['Odynasties Administrator',$email,password_hash($password,PASSWORD_DEFAULT)]);echo 'Admin created. Email: '.e($email).' Password: '.e($password).'<br>Delete this file now.';}else echo 'Admin already exists. Delete this file now.';
